-- opening stock ledger: current stock plus what was sold in the last 30 days, so the ledger adds up
INSERT INTO inventory_movements (product_id, warehouse_id, change_qty, reason, created_at)
SELECT i.product_id, i.warehouse_id, i.quantity_on_hand + s.sold, 'RESTOCK', now() - interval '45 days'
FROM inventory i CROSS JOIN LATERAL (SELECT COALESCE(-SUM(m.change_qty), 0)::INT AS sold FROM inventory_movements m
  WHERE m.product_id = i.product_id AND m.warehouse_id = i.warehouse_id AND m.reason = 'SALE') s
WHERE i.quantity_on_hand + s.sold > 0;
